export const migrations: { name: string; sql: string }[] = [
  { name: "00000000000000_init_schema.sql", sql: "-- =============================================================================\r\n-- IJFK - Migración inicial del esquema de base de datos\r\n-- =============================================================================\r\n-- Esta migración se ejecuta automáticamente al levantar el contenedor de\r\n-- Postgres por primera vez (carpeta /docker-entrypoint-initdb.d).\r\n--\r\n-- Idempotente: usa IF NOT EXISTS para permitir re-ejecución segura.\r\n-- =============================================================================\r\n\r\n-- Extensiones típicas de Supabase ---------------------------------------------\r\nCREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\r\nCREATE EXTENSION IF NOT EXISTS \"pgcrypto\";\r\nCREATE EXTENSION IF NOT EXISTS \"citext\";\r\n\r\n-- =============================================================================\r\n-- ENUMS\r\n-- =============================================================================\r\nDO $$ BEGIN\r\n  CREATE TYPE user_role AS ENUM ('admin', 'docente', 'padre');\r\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\r\n\r\nDO $$ BEGIN\r\n  CREATE TYPE shift_type AS ENUM ('Mañana', 'Tarde');\r\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\r\n\r\nDO $$ BEGIN\r\n  CREATE TYPE enrollment_status AS ENUM ('regular', 'condicional', 'pendiente');\r\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\r\n\r\nDO $$ BEGIN\r\n  CREATE TYPE attendance_status AS ENUM ('A', 'F', 'T', 'J');\r\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\r\n\r\nDO $$ BEGIN\r\n  CREATE TYPE announcement_category AS ENUM ('urgente', 'importante', 'general', 'informativo');\r\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\r\n\r\nDO $$ BEGIN\r\n  CREATE TYPE grade_level AS ENUM ('AD', 'A', 'B', 'C');\r\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\r\n\r\n-- =============================================================================\r\n-- Tabla: users\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS users (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  email CITEXT UNIQUE NOT NULL,\r\n  full_name TEXT NOT NULL,\r\n  role user_role NOT NULL,\r\n  phone TEXT,\r\n  avatar_url TEXT,\r\n  is_active BOOLEAN NOT NULL DEFAULT true,\r\n  email_verified_at TIMESTAMPTZ,\r\n  last_login_at TIMESTAMPTZ,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_users_role ON users(role);\r\nCREATE INDEX IF NOT EXISTS idx_users_active ON users(is_active);\r\n\r\n-- =============================================================================\r\n-- Tabla: students\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS students (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  dni TEXT UNIQUE NOT NULL,\r\n  full_name TEXT NOT NULL,\r\n  initials TEXT,\r\n  grade TEXT NOT NULL,\r\n  grade_num INT NOT NULL CHECK (grade_num BETWEEN 1 AND 6),\r\n  section TEXT NOT NULL,\r\n  shift shift_type NOT NULL DEFAULT 'Mañana',\r\n  parent_id UUID REFERENCES users(id) ON DELETE SET NULL,\r\n  enrollment_code TEXT UNIQUE,\r\n  enrolled_at DATE NOT NULL DEFAULT CURRENT_DATE,\r\n  status TEXT NOT NULL DEFAULT 'activo' CHECK (status IN ('activo','retirado','trasladado')),\r\n  avg_grade NUMERIC(4,2) DEFAULT 0,\r\n  attendance_rate INT DEFAULT 100,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_students_grade_section ON students(grade, section);\r\nCREATE INDEX IF NOT EXISTS idx_students_parent ON students(parent_id);\r\n\r\n-- =============================================================================\r\n-- Tabla: courses\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS courses (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  name TEXT NOT NULL,\r\n  grade TEXT NOT NULL,\r\n  section TEXT NOT NULL,\r\n  year INT NOT NULL DEFAULT EXTRACT(YEAR FROM now())::INT,\r\n  shift shift_type NOT NULL DEFAULT 'Mañana',\r\n  classroom TEXT,\r\n  teacher_id UUID REFERENCES users(id) ON DELETE SET NULL,\r\n  bimester INT NOT NULL DEFAULT 1 CHECK (bimester BETWEEN 1 AND 4),\r\n  hours_per_week INT DEFAULT 4,\r\n  students_total INT DEFAULT 0,\r\n  avg_grade NUMERIC(4,2) DEFAULT 0,\r\n  attendance_rate INT DEFAULT 100,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE(name, grade, section, year)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_courses_teacher ON courses(teacher_id);\r\nCREATE INDEX IF NOT EXISTS idx_courses_grade_section ON courses(grade, section);\r\n\r\n-- =============================================================================\r\n-- Tabla: grades (notas)\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS grades (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,\r\n  course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE,\r\n  bimester INT NOT NULL CHECK (bimester BETWEEN 1 AND 4),\r\n  n1 NUMERIC(4,2) CHECK (n1 BETWEEN 0 AND 20),\r\n  n2 NUMERIC(4,2) CHECK (n2 BETWEEN 0 AND 20),\r\n  n3 NUMERIC(4,2) CHECK (n3 BETWEEN 0 AND 20),\r\n  average NUMERIC(4,2) GENERATED ALWAYS AS (\r\n    CASE\r\n      WHEN n3 IS NOT NULL AND n3 > 0 THEN (COALESCE(n1,0) + COALESCE(n2,0) + COALESCE(n3,0)) / 3\r\n      ELSE (COALESCE(n1,0) + COALESCE(n2,0)) / 2\r\n    END\r\n  ) STORED,\r\n  level grade_level,\r\n  observation TEXT,\r\n  registered_by UUID REFERENCES users(id) ON DELETE SET NULL,\r\n  registered_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE(student_id, course_id, bimester)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_grades_student ON grades(student_id);\r\nCREATE INDEX IF NOT EXISTS idx_grades_course ON grades(course_id);\r\n\r\n-- =============================================================================\r\n-- Tabla: attendance\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS attendance (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,\r\n  date DATE NOT NULL,\r\n  status attendance_status NOT NULL DEFAULT 'A',\r\n  observation TEXT,\r\n  registered_by UUID REFERENCES users(id) ON DELETE SET NULL,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE(student_id, date)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(date);\r\nCREATE INDEX IF NOT EXISTS idx_attendance_student_date ON attendance(student_id, date);\r\n\r\n-- =============================================================================\r\n-- Tabla: enrollments (matrículas y pagos)\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS enrollments (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,\r\n  code TEXT UNIQUE NOT NULL,\r\n  year INT NOT NULL,\r\n  status enrollment_status NOT NULL DEFAULT 'pendiente',\r\n  docs_total INT DEFAULT 7,\r\n  docs_submitted INT DEFAULT 0,\r\n  apafa_paid BOOLEAN DEFAULT false,\r\n  apafa_amount NUMERIC(8,2) DEFAULT 50,\r\n  actividades_paid BOOLEAN DEFAULT false,\r\n  actividades_amount NUMERIC(8,2) DEFAULT 30,\r\n  last_payment_date DATE,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE(student_id, year)\r\n);\r\n\r\n-- =============================================================================\r\n-- Tabla: announcements (avisos)\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS announcements (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  category announcement_category NOT NULL DEFAULT 'general',\r\n  title TEXT NOT NULL,\r\n  body TEXT NOT NULL,\r\n  sender TEXT NOT NULL,\r\n  audience TEXT NOT NULL DEFAULT 'todos',\r\n  is_read BOOLEAN DEFAULT false,\r\n  published_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  expires_at TIMESTAMPTZ,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_announcements_published ON announcements(published_at DESC);\r\n\r\n-- =============================================================================\r\n-- Triggers para updated_at\r\n-- =============================================================================\r\nCREATE OR REPLACE FUNCTION set_updated_at()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n  NEW.updated_at = now();\r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\nDO $$\r\nDECLARE t TEXT;\r\nBEGIN\r\n  FOR t IN SELECT unnest(ARRAY['users','students','courses','grades','enrollments']) LOOP\r\n    EXECUTE format('\r\n      DROP TRIGGER IF EXISTS trg_%I_updated_at ON %I;\r\n      CREATE TRIGGER trg_%I_updated_at\r\n        BEFORE UPDATE ON %I\r\n        FOR EACH ROW EXECUTE FUNCTION set_updated_at();\r\n    ', t, t, t, t);\r\n  END LOOP;\r\nEND $$;\r\n\r\n-- =============================================================================\r\n-- Row Level Security (RLS) - Opcional pero recomendado\r\n-- =============================================================================\r\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE students ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE courses ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE grades ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE attendance ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE enrollments ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE announcements ENABLE ROW LEVEL SECURITY;\r\n\r\n-- Política permisiva para usuarios autenticados (ajustar según necesidad).\r\n-- OJO: el rol 'authenticated' solo existe en Supabase Cloud; en el Postgres\r\n-- local (Docker) no existe, así que solo se crean las políticas si el rol está.\r\n-- Sin este guard, `initdb.d` aborta aquí y no aplica las migraciones 001-006.\r\nDO $$\r\nDECLARE t TEXT;\r\nBEGIN\r\n  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN\r\n    FOR t IN SELECT unnest(ARRAY['users','students','courses','grades','attendance','enrollments','announcements']) LOOP\r\n      EXECUTE format('\r\n        DROP POLICY IF EXISTS \"Allow authenticated full access\" ON %I;\r\n        CREATE POLICY \"Allow authenticated full access\" ON %I\r\n          FOR ALL\r\n          TO authenticated\r\n          USING (true)\r\n          WITH CHECK (true);\r\n      ', t, t);\r\n    END LOOP;\r\n  END IF;\r\nEND $$;\r\n\r\n-- =============================================================================\r\n-- Datos de ejemplo (mock inicial) - solo si las tablas están vacías\r\n-- =============================================================================\r\nDO $$\r\nBEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM users) THEN\r\n    -- Admin por defecto\r\n    INSERT INTO users (email, full_name, role, is_active) VALUES\r\n      ('admin@ijfk.edu.pe', 'Administrador', 'admin', true),\r\n      ('director@ijfk.edu.pe', 'Prof. Rosa Quispe Tantavilca', 'admin', true);\r\n  END IF;\r\nEND $$;\r\n\r\n-- =============================================================================\r\n-- Comentarios de tabla\r\n-- =============================================================================\r\nCOMMENT ON TABLE users IS 'Usuarios del sistema (admin, docentes, padres)';\r\nCOMMENT ON TABLE students IS 'Estudiantes matriculados';\r\nCOMMENT ON TABLE courses IS 'Cursos / secciones por año académico';\r\nCOMMENT ON TABLE grades IS 'Calificaciones por bimestre';\r\nCOMMENT ON TABLE attendance IS 'Registro de asistencia diaria';\r\nCOMMENT ON TABLE enrollments IS 'Matrículas anuales y pagos';\r\nCOMMENT ON TABLE announcements IS 'Avisos y comunicados institucionales';\r\n" },
  { name: "00000000000001_registration.sql", sql: "-- =============================================================================\r\n-- IJFK - Migración: sistema de registro con verificación por email\r\n-- =============================================================================\r\n-- Agrega:\r\n--   - Tabla pending_registrations: registros pendientes de verificar por email\r\n--   - Columna email_verified_at en users (si no existe)\r\n--   - Trigger para auto-crear perfil al verificar\r\n-- =============================================================================\r\n\r\n-- Agregar columna email_verified_at a users si no existe\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.columns\r\n    WHERE table_name = 'users' AND column_name = 'email_verified_at'\r\n  ) THEN\r\n    ALTER TABLE users ADD COLUMN email_verified_at TIMESTAMPTZ;\r\n  END IF;\r\nEND $$;\r\n\r\n-- Agregar columna password_hash a users si no existe\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.columns\r\n    WHERE table_name = 'users' AND column_name = 'password_hash'\r\n  ) THEN\r\n    ALTER TABLE users ADD COLUMN password_hash TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\n-- Tabla de registros pendientes de verificación ---------------------------\r\nCREATE TABLE IF NOT EXISTS pending_registrations (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  email CITEXT UNIQUE NOT NULL,\r\n  full_name TEXT NOT NULL,\r\n  password_hash TEXT NOT NULL,\r\n  year TEXT NOT NULL,             -- \"1\", \"2\", \"3\", \"4\", \"5\"\r\n  section TEXT NOT NULL,          -- \"A\"...\"M\"\r\n  shift TEXT NOT NULL,            -- \"mañana\", \"tarde\"\r\n  verification_code TEXT NOT NULL, -- código de 6 dígitos\r\n  code_expires_at TIMESTAMPTZ NOT NULL,\r\n  attempts INT NOT NULL DEFAULT 0,\r\n  is_verified BOOLEAN NOT NULL DEFAULT false,\r\n  verified_at TIMESTAMPTZ,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_pending_email ON pending_registrations(email);\r\nCREATE INDEX IF NOT EXISTS idx_pending_code ON pending_registrations(verification_code);\r\nCREATE INDEX IF NOT EXISTS idx_pending_expires ON pending_registrations(code_expires_at);\r\n\r\n-- Trigger para updated_at\r\nDROP TRIGGER IF EXISTS trg_pending_updated_at ON pending_registrations;\r\nCREATE TRIGGER trg_pending_updated_at\r\n  BEFORE UPDATE ON pending_registrations\r\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\r\n\r\n-- Función para limpiar códigos expirados (puede ser invocada por cron)\r\nCREATE OR REPLACE FUNCTION cleanup_expired_pending_registrations()\r\nRETURNS INT AS $$\r\nDECLARE\r\n  deleted_count INT;\r\nBEGIN\r\n  DELETE FROM pending_registrations\r\n  WHERE code_expires_at < now() - INTERVAL '1 day';\r\n  GET DIAGNOSTICS deleted_count = ROW_COUNT;\r\n  RETURN deleted_count;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\n-- RLS -----------------------------------------------------------------------\r\nALTER TABLE pending_registrations ENABLE ROW LEVEL SECURITY;\r\n\r\n-- Política: permitir todo (server-side, sin auth para simplificar mock)\r\nDROP POLICY IF EXISTS \"Allow all\" ON pending_registrations;\r\nCREATE POLICY \"Allow all\" ON pending_registrations\r\n  FOR ALL\r\n  TO public\r\n  USING (true)\r\n  WITH CHECK (true);\r\n\r\n-- Comentarios\r\nCOMMENT ON TABLE pending_registrations IS\r\n  'Registros de usuarios pendientes de verificar su email. Tras verificar el código, se migran a la tabla users.';\r\nCOMMENT ON COLUMN pending_registrations.verification_code IS\r\n  'Código de 6 dígitos enviado por email. Expira en 15 minutos.';\r\nCOMMENT ON COLUMN pending_registrations.attempts IS\r\n  'Número de intentos de verificación fallidos.';\r\n" },
  { name: "00000000000002_password_recovery.sql", sql: "-- =============================================================================\r\n-- IJFK - Migración: cambio obligatorio de contraseña + recuperación\r\n-- =============================================================================\r\n-- Agrega:\r\n--   - Columna must_change_password en users (para forzar cambio tras primer login)\r\n--   - Tabla password_reset_codes: códigos temporales para recuperar contraseña\r\n-- =============================================================================\r\n\r\n-- Columna must_change_password en users\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.columns\r\n    WHERE table_name = 'users' AND column_name = 'must_change_password'\r\n  ) THEN\r\n    ALTER TABLE users ADD COLUMN must_change_password BOOLEAN NOT NULL DEFAULT false;\r\n  END IF;\r\nEND $$;\r\n\r\n-- Tabla de códigos de recuperación de contraseña\r\nCREATE TABLE IF NOT EXISTS password_reset_codes (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  email CITEXT NOT NULL,\r\n  code TEXT NOT NULL,\r\n  expires_at TIMESTAMPTZ NOT NULL,\r\n  used_at TIMESTAMPTZ,\r\n  attempts INT NOT NULL DEFAULT 0,\r\n  ip_address TEXT,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_reset_email ON password_reset_codes(email);\r\nCREATE INDEX IF NOT EXISTS idx_reset_code ON password_reset_codes(code);\r\nCREATE INDEX IF NOT EXISTS idx_reset_expires ON password_reset_codes(expires_at);\r\n\r\n-- Trigger updated_at (la tabla no tiene, pero no es crítico)\r\n\r\n-- RLS\r\nALTER TABLE password_reset_codes ENABLE ROW LEVEL SECURITY;\r\n\r\nDROP POLICY IF EXISTS \"Allow all reset codes\" ON password_reset_codes;\r\nCREATE POLICY \"Allow all reset codes\" ON password_reset_codes\r\n  FOR ALL\r\n  TO public\r\n  USING (true)\r\n  WITH CHECK (true);\r\n\r\n-- Comentarios\r\nCOMMENT ON COLUMN users.must_change_password IS\r\n  'Si true, el usuario debe cambiar su contraseña antes de poder usar el sistema.';\r\nCOMMENT ON TABLE password_reset_codes IS\r\n  'Códigos de un solo uso para recuperación de contraseña. Expiran en 30 minutos.';\r\n" },
  { name: "00000000000003_schedules_materials.sql", sql: "-- =============================================================================\r\n-- IJFK - Migración: horarios (schedule_entries) y materiales (materials)\r\n-- =============================================================================\r\n-- Agrega:\r\n--   - Tabla schedule_entries: horario semanal por grado/sección\r\n--   - Tabla materials: materiales de clase por curso\r\n--   - Columnas extra en enrollments: docs (JSONB), tutor, classroom\r\n--\r\n-- Idempotente: usa IF NOT EXISTS / ADD COLUMN IF NOT EXISTS.\r\n-- =============================================================================\r\n\r\n-- =============================================================================\r\n-- Tabla: schedule_entries (horario semanal por sección)\r\n-- =============================================================================\r\n-- Una fila = un período de un día para una sección (grado + sección).\r\n-- El horario del padre se obtiene por grade/section del hijo;\r\n-- el del docente filtrando por el nombre del docente (columna teacher).\r\nCREATE TABLE IF NOT EXISTS schedule_entries (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  grade TEXT NOT NULL,              -- \"1ro\"...\"5to\"\r\n  section TEXT NOT NULL,            -- \"A\", \"B\", ...\r\n  -- Sin CHECK de valores: 'Miércoles' puede llegar en distinta normalización\r\n  -- Unicode (NFC/NFD) según el editor y rompería la comparación del CHECK.\r\n  day TEXT NOT NULL,              -- 'Lunes'..'Viernes'\r\n  period INT NOT NULL CHECK (period BETWEEN 1 AND 7),\r\n  time TEXT NOT NULL,               -- \"7:45 - 8:30\"\r\n  subject TEXT NOT NULL,\r\n  teacher TEXT,                     -- nombre visible del docente\r\n  room TEXT,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE(grade, section, day, period)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_schedule_grade_section ON schedule_entries(grade, section);\r\nCREATE INDEX IF NOT EXISTS idx_schedule_teacher ON schedule_entries(teacher);\r\n\r\n-- =============================================================================\r\n-- Tabla: materials (materiales de clase por curso)\r\n-- =============================================================================\r\nCREATE TABLE IF NOT EXISTS materials (\r\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n  course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE,\r\n  title TEXT NOT NULL,\r\n  type TEXT NOT NULL CHECK (type IN ('pdf','pptx','docx','xlsx','img')),\r\n  size TEXT,\r\n  topic TEXT,\r\n  uploaded_at DATE NOT NULL DEFAULT CURRENT_DATE,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_materials_course ON materials(course_id);\r\n\r\n-- =============================================================================\r\n-- Columnas extra en enrollments (detalle de documentos, tutor y aula)\r\n-- =============================================================================\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.columns\r\n    WHERE table_name = 'enrollments' AND column_name = 'docs'\r\n  ) THEN\r\n    ALTER TABLE enrollments ADD COLUMN docs JSONB NOT NULL DEFAULT '[]'::jsonb;\r\n  END IF;\r\nEND $$;\r\n\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.columns\r\n    WHERE table_name = 'enrollments' AND column_name = 'tutor'\r\n  ) THEN\r\n    ALTER TABLE enrollments ADD COLUMN tutor TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.columns\r\n    WHERE table_name = 'enrollments' AND column_name = 'classroom'\r\n  ) THEN\r\n    ALTER TABLE enrollments ADD COLUMN classroom TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\n-- =============================================================================\r\n-- Row Level Security (mismo patrón permisivo que el resto del esquema)\r\n-- =============================================================================\r\nALTER TABLE schedule_entries ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE materials ENABLE ROW LEVEL SECURITY;\r\n\r\n-- Nota: el rol 'authenticated' solo existe en Supabase Cloud; en el Postgres\r\n-- local (Docker) no existe, así que solo creamos las políticas si el rol está.\r\nDO $$\r\nDECLARE t TEXT;\r\nBEGIN\r\n  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN\r\n    FOR t IN SELECT unnest(ARRAY['schedule_entries','materials']) LOOP\r\n      EXECUTE format('\r\n        DROP POLICY IF EXISTS \"Allow authenticated full access\" ON %I;\r\n        CREATE POLICY \"Allow authenticated full access\" ON %I\r\n          FOR ALL\r\n          TO authenticated\r\n          USING (true)\r\n          WITH CHECK (true);\r\n      ', t, t);\r\n    END LOOP;\r\n  END IF;\r\nEND $$;\r\n\r\n-- =============================================================================\r\n-- Comentarios\r\n-- =============================================================================\r\nCOMMENT ON TABLE schedule_entries IS 'Horario semanal por grado/sección (un período por fila)';\r\nCOMMENT ON TABLE materials IS 'Materiales de clase publicados por los docentes';\r\nCOMMENT ON COLUMN enrollments.docs IS 'Checklist de documentos: [{label, submitted}]';\r\n" },
  { name: "00000000000004_rls_policies.sql", sql: "-- =============================================================================\r\n-- IJFK - Migración: políticas RLS reales por rol (DEFENSA EN PROFUNDIDAD)\r\n-- =============================================================================\r\n-- Refuerza seguridad a nivel de base de datos (no solo en la app).\r\n--\r\n-- Las API routes de IJFK se conectan con `supabase_admin` (superuser que\r\n-- ignora RLS), así que estas políticas NO afectan al funcionamiento de la\r\n-- app en desarrollo: son una segunda línea de defensa para despliegues que\r\n-- usen clientes con roles `authenticated`/`anon` (típicamente Supabase Cloud\r\n-- con auth integrada y conexiones directas desde el navegador o un client\r\n-- server con service-role key limitada).\r\n--\r\n-- Modelo (compatible con el esquema actual):\r\n--   * users         → lectura: el propio usuario o admin. Escritura: admin.\r\n--   * students      → padre ve solo sus hijos (parent_id = auth.uid());\r\n--                    docente/admin ven todos. Escritura: admin.\r\n--   * courses       → docente ve los suyos (teacher_id = auth.uid());\r\n--                    admin/padre (lectura) ven los asociados a sus hijos.\r\n--   * grades        → padre ve notas de sus hijos; docente las de sus cursos;\r\n--                    admin ve todo. Escritura: docente que posee el curso o admin.\r\n--   * attendance    → igual que grades.\r\n--   * enrollments   → padre las de sus hijos; docente/admin ven todo.\r\n--   * schedule_entries → lectura por padres cuyos hijos están en la sección;\r\n--                    docente dueño de la sección (vía courses) y admin.\r\n--   * materials     → docente dueño del curso; admin; padre (lectura) si tiene\r\n--                    hijo en esa sección.\r\n--   * announcements → lectura: todos los autenticados; escritura: admin.\r\n--\r\n-- IMPORTANTE: como en este entorno local no existen los roles `authenticated`\r\n-- ni las funciones `auth.uid()` / `auth.jwt()`, todas las policies se crean\r\n-- solo si esas infraestructuras están presentes. En un entorno sin auth de\r\n-- Supabase esto queda como no-op (la app ya filtra en sus queries), y en\r\n-- Supabase Cloud sí aplica.\r\n-- =============================================================================\r\n\r\n-- Helper: ¿está presente auth.uid()?\r\n-- (En Supabase Cloud existe la función auth.uid(); localmente no.)\r\nDO $$\r\nBEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'auth' AND p.proname = 'uid'\r\n  ) THEN\r\n    -- Sin auth.uid(): salir sin tocar policies. La app ya hace cumplir el rol.\r\n    RAISE NOTICE 'auth.uid() no disponible: saltando políticas RLS.';\r\n    RETURN;\r\n  END IF;\r\n\r\n  -- Activar RLS en todas las tablas (revocar acceso público implícito)\r\n  ALTER TABLE users         ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE students      ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE courses       ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE grades        ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE attendance    ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE enrollments   ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE announcements ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE schedule_entries ENABLE ROW LEVEL SECURITY;\r\n  ALTER TABLE materials     ENABLE ROW LEVEL SECURITY;\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- users\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"users_select_self_or_admin\" ON users;\r\n  CREATE POLICY \"users_select_self_or_admin\" ON users\r\n    FOR SELECT TO authenticated\r\n    USING (id = auth.uid() OR EXISTS (\r\n      SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'\r\n    ));\r\n\r\n  DROP POLICY IF EXISTS \"users_modify_admin\" ON users;\r\n  CREATE POLICY \"users_modify_admin\" ON users\r\n    FOR ALL TO authenticated\r\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\r\n    WITH CHECK (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- students\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"students_select_role\" ON students;\r\n  CREATE POLICY \"students_select_role\" ON students\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      parent_id = auth.uid()\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role IN ('admin','docente'))\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"students_write_admin\" ON students;\r\n  CREATE POLICY \"students_write_admin\" ON students\r\n    FOR ALL TO authenticated\r\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\r\n    WITH CHECK (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- courses\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"courses_select_role\" ON courses;\r\n  CREATE POLICY \"courses_select_role\" ON courses\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      teacher_id = auth.uid()\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n      -- padre: si tiene un hijo en esa sección\r\n      OR EXISTS (\r\n        SELECT 1 FROM students s\r\n        WHERE s.parent_id = auth.uid()\r\n          AND s.grade = courses.grade AND s.section = courses.section\r\n      )\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"courses_write_admin\" ON courses;\r\n  CREATE POLICY \"courses_write_admin\" ON courses\r\n    FOR ALL TO authenticated\r\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\r\n    WITH CHECK (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- grades\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"grades_select_role\" ON grades;\r\n  CREATE POLICY \"grades_select_role\" ON grades\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM students s WHERE s.id = grades.student_id AND s.parent_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM courses c WHERE c.id = grades.course_id AND c.teacher_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"grades_write_teacher_or_admin\" ON grades;\r\n  CREATE POLICY \"grades_write_teacher_or_admin\" ON grades\r\n    FOR ALL TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = grades.course_id AND c.teacher_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    )\r\n    WITH CHECK (\r\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = grades.course_id AND c.teacher_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    );\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- attendance\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"attendance_select_role\" ON attendance;\r\n  CREATE POLICY \"attendance_select_role\" ON attendance\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM students s WHERE s.id = attendance.student_id AND s.parent_id = auth.uid())\r\n      OR EXISTS (\r\n        SELECT 1 FROM students s, courses c\r\n        WHERE s.id = attendance.student_id AND c.teacher_id = auth.uid()\r\n          AND s.grade = c.grade AND s.section = c.section\r\n      )\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"attendance_write_teacher_or_admin\" ON attendance;\r\n  CREATE POLICY \"attendance_write_teacher_or_admin\" ON attendance\r\n    FOR ALL TO authenticated\r\n    USING (\r\n      EXISTS (\r\n        SELECT 1 FROM students s, courses c\r\n        WHERE s.id = attendance.student_id AND c.teacher_id = auth.uid()\r\n          AND s.grade = c.grade AND s.section = c.section\r\n      )\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    )\r\n    WITH CHECK (\r\n      EXISTS (\r\n        SELECT 1 FROM students s, courses c\r\n        WHERE s.id = attendance.student_id AND c.teacher_id = auth.uid()\r\n          AND s.grade = c.grade AND s.section = c.section\r\n      )\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    );\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- enrollments\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"enrollments_select_role\" ON enrollments;\r\n  CREATE POLICY \"enrollments_select_role\" ON enrollments\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM students s WHERE s.id = enrollments.student_id AND s.parent_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role IN ('admin','docente'))\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"enrollments_write_admin\" ON enrollments;\r\n  CREATE POLICY \"enrollments_write_admin\" ON enrollments\r\n    FOR ALL TO authenticated\r\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\r\n    WITH CHECK (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- announcements\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"announcements_select_any_authenticated\" ON announcements;\r\n  CREATE POLICY \"announcements_select_any_authenticated\" ON announcements\r\n    FOR SELECT TO authenticated\r\n    USING (true);\r\n\r\n  DROP POLICY IF EXISTS \"announcements_write_admin\" ON announcements;\r\n  CREATE POLICY \"announcements_write_admin\" ON announcements\r\n    FOR ALL TO authenticated\r\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\r\n    WITH CHECK (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- schedule_entries\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"schedule_select_role\" ON schedule_entries;\r\n  CREATE POLICY \"schedule_select_role\" ON schedule_entries\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n      -- padre con hijo en esa sección\r\n      OR EXISTS (\r\n        SELECT 1 FROM students s\r\n        WHERE s.parent_id = auth.uid()\r\n          AND s.grade = schedule_entries.grade AND s.section = schedule_entries.section\r\n      )\r\n      -- docente: si tiene un curso en esa sección\r\n      OR EXISTS (\r\n        SELECT 1 FROM courses c\r\n        WHERE c.teacher_id = auth.uid()\r\n          AND c.grade = schedule_entries.grade AND c.section = schedule_entries.section\r\n      )\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"schedule_write_admin\" ON schedule_entries;\r\n  CREATE POLICY \"schedule_write_admin\" ON schedule_entries\r\n    FOR ALL TO authenticated\r\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\r\n    WITH CHECK (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\r\n\r\n  -- -------------------------------------------------------------------------\r\n  -- materials\r\n  -- -------------------------------------------------------------------------\r\n  DROP POLICY IF EXISTS \"materials_select_role\" ON materials;\r\n  CREATE POLICY \"materials_select_role\" ON materials\r\n    FOR SELECT TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = materials.course_id AND c.teacher_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n      -- padre con hijo en la sección del curso\r\n      OR EXISTS (\r\n        SELECT 1 FROM courses c, students s\r\n        WHERE c.id = materials.course_id\r\n          AND s.parent_id = auth.uid()\r\n          AND s.grade = c.grade AND s.section = c.section\r\n      )\r\n    );\r\n\r\n  DROP POLICY IF EXISTS \"materials_write_teacher_or_admin\" ON materials;\r\n  CREATE POLICY \"materials_write_teacher_or_admin\" ON materials\r\n    FOR ALL TO authenticated\r\n    USING (\r\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = materials.course_id AND c.teacher_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    )\r\n    WITH CHECK (\r\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = materials.course_id AND c.teacher_id = auth.uid())\r\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\r\n    );\r\nEND $$;" },
  { name: "00000000000005_refinamiento_schema.sql", sql: "-- =============================================================================\r\n-- IJFK - Migración 005: refinamiento del esquema\r\n-- =============================================================================\r\n-- Añade:\r\n--   - users.subject: asignatura del docente\r\n--   - users.shift_preference: Mañana / Tarde / Ambos (docentes)\r\n--   - users.default_grade/section/shift: datos del hijo que el padre declaró\r\n--   - students.grade_num: CHECK 1-5 (solo secundaria, antes 1-6)\r\n--   - students.parent_claimed_at: auditoría de reclamo\r\n--   - grades.letter_grade: letra A/B/C/D generada desde average\r\n--\r\n-- Idempotente. No rompe datos existentes (columnas opcionales, NULL default).\r\n-- =============================================================================\r\n\r\n-- 1. users: columnas nuevas\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='subject') THEN\r\n    ALTER TABLE users ADD COLUMN subject TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='shift_preference') THEN\r\n    ALTER TABLE users ADD COLUMN shift_preference TEXT DEFAULT 'Ambos';\r\n  END IF;\r\nEND $$;\r\n\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='default_grade') THEN\r\n    ALTER TABLE users ADD COLUMN default_grade TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='default_section') THEN\r\n    ALTER TABLE users ADD COLUMN default_section TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='default_shift') THEN\r\n    ALTER TABLE users ADD COLUMN default_shift TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\n-- 2. students: ajustar CHECK de grade_num a 1-5 (solo secundaria)\r\nALTER TABLE students DROP CONSTRAINT IF EXISTS students_grade_num_check;\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM information_schema.table_constraints\r\n    WHERE table_name='students' AND constraint_name='students_grade_num_check'\r\n  ) THEN\r\n    ALTER TABLE students ADD CONSTRAINT students_grade_num_check\r\n      CHECK (grade_num BETWEEN 1 AND 5);\r\n  END IF;\r\nEND $$;\r\n\r\n-- 3. students: auditoría de reclamo\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='students' AND column_name='parent_claimed_at') THEN\r\n    ALTER TABLE students ADD COLUMN parent_claimed_at TIMESTAMPTZ;\r\n  END IF;\r\nEND $$;\r\n\r\n-- 4. grades: letra generada desde average (A/B/C/D)\r\n-- Nota: no podemos usar GENERATED ALWAYS AS (...) porque `average` ya es una\r\n-- columna GENERATED de Postgres, y una columna generada no puede referenciar\r\n-- a otra generada. Usamos una columna normal + trigger BEFORE INSERT/UPDATE.\r\nDO $$ BEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='grades' AND column_name='letter_grade') THEN\r\n    ALTER TABLE grades ADD COLUMN letter_grade TEXT;\r\n  END IF;\r\nEND $$;\r\n\r\n-- Función que calcula la letra desde n1/n2/n3 (replica la lógica de `average`)\r\nCREATE OR REPLACE FUNCTION compute_letter_grade()\r\nRETURNS TRIGGER AS $$\r\nDECLARE\r\n  calc_avg NUMERIC(4,2);\r\nBEGIN\r\n  IF NEW.n3 IS NOT NULL AND NEW.n3 > 0 THEN\r\n    calc_avg := (COALESCE(NEW.n1, 0) + COALESCE(NEW.n2, 0) + COALESCE(NEW.n3, 0)) / 3;\r\n  ELSE\r\n    calc_avg := (COALESCE(NEW.n1, 0) + COALESCE(NEW.n2, 0)) / 2;\r\n  END IF;\r\n\r\n  IF NEW.n1 IS NULL AND NEW.n2 IS NULL AND NEW.n3 IS NULL THEN\r\n    NEW.letter_grade := NULL;\r\n  ELSIF calc_avg >= 18 THEN\r\n    NEW.letter_grade := 'A';\r\n  ELSIF calc_avg >= 15 THEN\r\n    NEW.letter_grade := 'B';\r\n  ELSIF calc_avg >= 10 THEN\r\n    NEW.letter_grade := 'C';\r\n  ELSE\r\n    NEW.letter_grade := 'D';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\nDROP TRIGGER IF EXISTS trg_grades_letter ON grades;\r\nCREATE TRIGGER trg_grades_letter\r\n  BEFORE INSERT OR UPDATE OF n1, n2, n3 ON grades\r\n  FOR EACH ROW EXECUTE FUNCTION compute_letter_grade();\r\n\r\n-- 5. Índice útil para courses por (grade, section, year)\r\nCREATE INDEX IF NOT EXISTS idx_courses_grade_section_year\r\n  ON courses(grade, section, year);\r\n\r\n-- 6. Comentarios\r\nCOMMENT ON COLUMN users.subject IS 'Asignatura del docente (NULL si no es docente)';\r\nCOMMENT ON COLUMN users.shift_preference IS 'Mañana, Tarde o Ambos (docentes)';\r\nCOMMENT ON COLUMN users.default_grade IS 'Grado del hijo declarado al registrarse (padres)';\r\nCOMMENT ON COLUMN users.default_section IS 'Sección del hijo declarado al registrarse (padres)';\r\nCOMMENT ON COLUMN users.default_shift IS 'Turno del hijo declarado al registrarse (padres)';\r\nCOMMENT ON COLUMN students.parent_claimed_at IS 'Fecha en que el apoderado reclamó al hijo via enrollment_code';\r\nCOMMENT ON COLUMN grades.letter_grade IS 'A(18-20) B(15-17) C(10-14) D(0-9). NULL si average es NULL.';\r\n" },
  { name: "00000000000006_padres_mejoras.sql", sql: "-- =============================================================================\n-- IJFK - Migración 006: mejoras del panel de padres\n-- =============================================================================\n-- Agrega:\n--   - Tabla attendance_justifications: solicitudes del padre para justificar\n--     una falta; el docente las aprueba/rechaza (al aprobar, la asistencia\n--     pasa a 'J').\n--   - Tabla announcement_reads: avisos leídos por usuario (permite que cada\n--     padre/docente tenga su propio estado de lectura sin tocar is_read global).\n--\n-- Idempotente: usa IF NOT EXISTS / DO $$ guards. Se aplica automáticamente al\n-- primer arranque del contenedor (docker-entrypoint-initdb.d), igual que las\n-- migraciones 000-005.\n-- =============================================================================\n\n-- =============================================================================\n-- Tabla: attendance_justifications\n-- =============================================================================\nCREATE TABLE IF NOT EXISTS attendance_justifications (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  attendance_id UUID NOT NULL REFERENCES attendance(id) ON DELETE CASCADE,\n  student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,\n  parent_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  reason TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pendiente'\n    CHECK (status IN ('pendiente', 'aprobada', 'rechazada')),\n  admin_response TEXT,\n  reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  reviewed_at TIMESTAMPTZ,\n  UNIQUE(attendance_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_justifications_status ON attendance_justifications(status);\nCREATE INDEX IF NOT EXISTS idx_justifications_student ON attendance_justifications(student_id);\nCREATE INDEX IF NOT EXISTS idx_justifications_attendance ON attendance_justifications(attendance_id);\n\n-- =============================================================================\n-- Tabla: announcement_reads (lectura de avisos por usuario)\n-- =============================================================================\nCREATE TABLE IF NOT EXISTS announcement_reads (\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  announcement_id UUID NOT NULL REFERENCES announcements(id) ON DELETE CASCADE,\n  read_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  PRIMARY KEY (user_id, announcement_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_announcement_reads_announcement\n  ON announcement_reads(announcement_id);\n\n-- =============================================================================\n-- Row Level Security (mismo patrón permisivo que el resto del esquema)\n-- =============================================================================\nALTER TABLE attendance_justifications ENABLE ROW LEVEL SECURITY;\nALTER TABLE announcement_reads ENABLE ROW LEVEL SECURITY;\n\n-- Nota: el rol 'authenticated' solo existe en Supabase Cloud; en el Postgres\n-- local (Docker) no existe, así que solo creamos las políticas si el rol está.\nDO $$\nDECLARE t TEXT;\nBEGIN\n  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN\n    FOR t IN SELECT unnest(ARRAY['attendance_justifications','announcement_reads']) LOOP\n      EXECUTE format('\n        DROP POLICY IF EXISTS \"Allow authenticated full access\" ON %I;\n        CREATE POLICY \"Allow authenticated full access\" ON %I\n          FOR ALL\n          TO authenticated\n          USING (true)\n          WITH CHECK (true);\n      ', t, t);\n    END LOOP;\n  END IF;\nEND $$;\n\n-- =============================================================================\n-- Comentarios\n-- =============================================================================\nCOMMENT ON TABLE attendance_justifications\n  IS 'Solicitud del padre para justificar una falta. Al aprobar el docente, attendance.status pasa a J.';\nCOMMENT ON COLUMN attendance_justifications.status\n  IS 'pendiente | aprobada | rechazada';\nCOMMENT ON TABLE announcement_reads\n  IS 'Aviso marcado como leído por un usuario concreto (estado por usuario).';\n" },
  { name: "00000000000007_schedule_teacher_id.sql", sql: "-- =============================================================================\n-- IJFK - Migración: schedule_entries.teacher_id (FK a users)\n-- =============================================================================\n-- schedule_entries.teacher era texto libre (nombre visible) comparado contra\n-- users.full_name para resolver el horario del docente autenticado\n-- (app/api/teacher/schedule/route.ts) y para detectar choques de horario en\n-- el editor drag-and-drop del admin (app/admin/schedule/page.tsx). Eso rompe\n-- en dos casos: dos docentes con el mismo nombre completo verían/chocarían\n-- con el horario del otro, y si un admin edita el full_name de un docente,\n-- su horario deja de coincidir silenciosamente.\n--\n-- Se agrega teacher_id (FK real) y se hace el backfill contra `courses`\n-- (grade+section+subject=name), que sí tiene un teacher_id real y unívoco\n-- por curso; `teacher` se conserva como nombre visible para no romper el\n-- texto ya mostrado en el grid del admin.\n--\n-- Nota: el backfill NO se hace por nombre — el seed de datos demo reutiliza\n-- el mismo full_name (\"Prof. Luis Ramos\", etc.) en varias cuentas docente\n-- distintas, así que un match por nombre asigna filas a una cuenta\n-- arbitraria entre las que calzan. El join contra courses es unívoco\n-- (UNIQUE(grade, section, subject=name) verificado contra los datos reales).\n--\n-- Idempotente: ADD COLUMN IF NOT EXISTS; el UPDATE recalcula siempre desde\n-- courses (no es un backfill de una sola vez condicionado a IS NULL), así\n-- que reaplicar esta migración corrige teacher_id si courses cambió.\n-- =============================================================================\n\nALTER TABLE schedule_entries ADD COLUMN IF NOT EXISTS teacher_id UUID REFERENCES users(id);\n\nUPDATE schedule_entries se\nSET teacher_id = c.teacher_id\nFROM courses c\nWHERE c.grade = se.grade\n  AND c.section = se.section\n  AND c.name = se.subject\n  AND se.teacher_id IS DISTINCT FROM c.teacher_id;\n\nCREATE INDEX IF NOT EXISTS idx_schedule_teacher_id ON schedule_entries(teacher_id);\n\nCOMMENT ON COLUMN schedule_entries.teacher_id IS 'Docente dueño del período (FK real); teacher sigue siendo el nombre visible para el grid';\n" },
  { name: "00000000000008_competencias.sql", sql: "-- =============================================================================\n-- IJFK - Migración 008: notas por competencia (libreta SIAGIE)\n-- =============================================================================\n-- El sistema pasa de un modelo PLANO (una nota por curso, columnas n1/n2/n3\n-- en `grades`) a un modelo POR COMPETENCIA, calcado de la libreta oficial\n-- (\"INFORME DE PROGRESO DE LAS COMPETENCIAS DEL ESTUDIANTE\"): cada área\n-- curricular tiene varias competencias, y cada competencia recibe un nivel\n-- de logro (AD/A/B/C) por bimestre + una conclusión descriptiva.\n--\n-- Esta migración es 100% ADITIVA: `grades`, su trigger de letra y sus 7\n-- lectores actuales siguen funcionando exactamente igual. La retirada de\n-- `grades` (rename a grades_legacy) es una migración futura aparte, una vez\n-- que el resto de la app ya lea de aquí.\n--\n-- Escala nueva (reemplaza la vieja A 18-20/B 15-17/C 10-14/D 0-9 del\n-- trigger de la migración 005): C 0-10, B 11-15, A 16-17, AD 18-20.\n-- Reutiliza el enum `grade_level` ('AD','A','B','C') ya existente\n-- (init_schema.sql) — hoy es una columna muerta en `grades.level`, nadie la\n-- escribe; aquí pasa a ser la letra real de cada nota.\n--\n-- Catálogo (11 áreas + 1 bloque transversal, 31 competencias): Tutoría,\n-- Cívica y HGE desaparecen como áreas — Cívica se absorbe en Desarrollo\n-- Personal/Ciudadanía y HGE en Ciencias Sociales — y entra Castellano como\n-- Segunda Lengua. Las horas semanales sí suman 35 (5 días × 7 períodos),\n-- el invariante que usa el generador de horarios de scripts/seed-full.mjs.\n--\n-- Las competencias transversales no pertenecen a ningún curso/área: las\n-- califica el tutor de la sección (tabla `section_tutors`, nueva) o el\n-- admin. `section_tutors` también reemplaza la dependencia que tenía\n-- `enrollments.tutor` del curso \"Tutoría\", que desaparece.\n--\n-- Idempotente: catálogo con ON CONFLICT DO UPDATE (reaplicar corrige\n-- textos/horas); tablas y columnas con IF NOT EXISTS.\n-- =============================================================================\n\n-- ─── 1. Escala de nivel de logro ─────────────────────────────────────────────\n-- Fuente de verdad SQL; espejo de lib/grades/scale.ts (levelFromScore).\nCREATE OR REPLACE FUNCTION nivel_logro(score NUMERIC)\nRETURNS grade_level\nLANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$\n  SELECT CASE\n    WHEN score IS NULL THEN NULL\n    WHEN score >= 18 THEN 'AD'\n    WHEN score >= 16 THEN 'A'\n    WHEN score >= 11 THEN 'B'\n    ELSE 'C'\n  END::grade_level\n$$;\nCOMMENT ON FUNCTION nivel_logro IS 'Escala oficial: C 0-10, B 11-15, A 16-17, AD 18-20. Espejo TS en lib/grades/scale.ts';\n\n-- ─── 2. Catálogo: áreas curriculares ──────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS curricular_areas (\n  id             SMALLINT PRIMARY KEY,\n  code           TEXT UNIQUE NOT NULL,\n  name           TEXT NOT NULL,\n  short_name     TEXT NOT NULL,\n  is_transversal BOOLEAN NOT NULL DEFAULT false,\n  hours_per_week SMALLINT NOT NULL DEFAULT 0,\n  color_key      TEXT NOT NULL DEFAULT 'slate',\n  display_order  SMALLINT NOT NULL,\n  active         BOOLEAN NOT NULL DEFAULT true\n);\n\nINSERT INTO curricular_areas (id, code, name, short_name, is_transversal, hours_per_week, color_key, display_order) VALUES\n  (1,  'DPCC',  'Desarrollo Personal, Ciudadanía y Cívica', 'DPCC',        false, 3, 'rose',     1),\n  (2,  'CCSS',  'Ciencias Sociales',                        'C. Sociales', false, 3, 'amber',    2),\n  (3,  'REL',   'Educación Religiosa',                      'Religión',    false, 2, 'violet',   3),\n  (4,  'EPT',   'Educación para el Trabajo',                'EPT',         false, 2, 'orange',   4),\n  (5,  'EDF',   'Educación Física',                         'Ed. Física',  false, 2, 'lime',     5),\n  (6,  'COM',   'Comunicación',                              'Comunicación', false, 6, 'purple',  6),\n  (7,  'ART',   'Arte y Cultura',                            'Arte',        false, 2, 'fuchsia',  7),\n  (8,  'CSL',   'Castellano como Segunda Lengua',            'Castellano 2L', false, 2, 'teal',    8),\n  (9,  'ING',   'Inglés',                                    'Inglés',      false, 3, 'cyan',     9),\n  (10, 'MAT',   'Matemática',                                'Matemática',  false, 6, 'blue',    10),\n  (11, 'CYT',   'Ciencia y Tecnología',                      'CyT',         false, 4, 'emerald', 11),\n  (12, 'TRANS', 'Competencias Transversales',                'Transversal', true,  0, 'slate',   12)\nON CONFLICT (id) DO UPDATE SET\n  code = EXCLUDED.code, name = EXCLUDED.name, short_name = EXCLUDED.short_name,\n  is_transversal = EXCLUDED.is_transversal, hours_per_week = EXCLUDED.hours_per_week,\n  color_key = EXCLUDED.color_key, display_order = EXCLUDED.display_order, active = true;\n\n-- Invariante del generador de horarios: 5 días × 7 períodos = 35.\nDO $$ BEGIN\n  IF (SELECT sum(hours_per_week) FROM curricular_areas WHERE active) <> 35 THEN\n    RAISE EXCEPTION 'curricular_areas.hours_per_week debe sumar 35 (suma actual: %)',\n      (SELECT sum(hours_per_week) FROM curricular_areas WHERE active);\n  END IF;\nEND $$;\n\n-- ─── 3. Catálogo: competencias ────────────────────────────────────────────────\n-- id = area_id*100 + n (natural, legible, sin necesidad de resolver UUIDs\n-- en el seed). Texto oficial íntegro de la libreta (sin abreviar).\nCREATE TABLE IF NOT EXISTS competencies (\n  id            SMALLINT PRIMARY KEY,\n  area_id       SMALLINT NOT NULL REFERENCES curricular_areas(id) ON DELETE RESTRICT,\n  code          TEXT UNIQUE NOT NULL,\n  name          TEXT NOT NULL,\n  display_order SMALLINT NOT NULL,\n  active        BOOLEAN NOT NULL DEFAULT true,\n  UNIQUE (area_id, display_order)\n);\n\nINSERT INTO competencies (id, area_id, code, name, display_order) VALUES\n  -- 1. Desarrollo Personal, Ciudadanía y Cívica\n  (101, 1, 'DPCC-1', 'Construye su identidad.', 1),\n  (102, 1, 'DPCC-2', 'Convive y participa democráticamente en la búsqueda del bien común.', 2),\n  -- 2. Ciencias Sociales\n  (201, 2, 'CCSS-1', 'Construye interpretaciones históricas.', 1),\n  (202, 2, 'CCSS-2', 'Gestiona responsablemente el espacio y el ambiente.', 2),\n  (203, 2, 'CCSS-3', 'Gestiona responsablemente los recursos económicos.', 3),\n  -- 3. Educación Religiosa\n  (301, 3, 'REL-1', 'Construye su identidad como persona humana, amada por Dios, digna, libre y trascendente, comprendiendo la doctrina de su propia religión, abierto al diálogo con las que le son cercanas.', 1),\n  (302, 3, 'REL-2', 'Asume la experiencia del encuentro personal y comunitario con Dios en su proyecto de vida en coherencia con su creencia religiosa.', 2),\n  -- 4. Educación para el Trabajo\n  (401, 4, 'EPT-1', 'Gestiona proyectos de emprendimiento económico o social.', 1),\n  -- 5. Educación Física\n  (501, 5, 'EDF-1', 'Se desenvuelve de manera autónoma a través de su motricidad.', 1),\n  (502, 5, 'EDF-2', 'Asume una vida saludable.', 2),\n  (503, 5, 'EDF-3', 'Interactúa a través de sus habilidades sociomotrices.', 3),\n  -- 6. Comunicación\n  (601, 6, 'COM-1', 'Se comunica oralmente en su lengua materna.', 1),\n  (602, 6, 'COM-2', 'Lee diversos tipos de textos escritos en su lengua materna.', 2),\n  (603, 6, 'COM-3', 'Escribe diversos tipos de textos en su lengua materna.', 3),\n  -- 7. Arte y Cultura\n  (701, 7, 'ART-1', 'Aprecia de manera crítica manifestaciones artístico-culturales.', 1),\n  (702, 7, 'ART-2', 'Crea proyectos desde los lenguajes artísticos.', 2),\n  -- 8. Castellano como Segunda Lengua\n  (801, 8, 'CSL-1', 'Se comunica oralmente.', 1),\n  (802, 8, 'CSL-2', 'Lee diversos tipos de textos.', 2),\n  (803, 8, 'CSL-3', 'Escribe diversos tipos de textos.', 3),\n  -- 9. Inglés\n  (901, 9, 'ING-1', 'Se comunica oralmente.', 1),\n  (902, 9, 'ING-2', 'Lee diversos tipos de textos.', 2),\n  (903, 9, 'ING-3', 'Escribe diversos tipos de textos.', 3),\n  -- 10. Matemática\n  (1001, 10, 'MAT-1', 'Resuelve problemas de cantidad.', 1),\n  (1002, 10, 'MAT-2', 'Resuelve problemas de regularidad, equivalencia y cambio.', 2),\n  (1003, 10, 'MAT-3', 'Resuelve problemas de forma, movimiento y localización.', 3),\n  (1004, 10, 'MAT-4', 'Resuelve problemas de gestión de datos e incertidumbre.', 4),\n  -- 11. Ciencia y Tecnología\n  (1101, 11, 'CYT-1', 'Indaga mediante métodos científicos para construir sus conocimientos.', 1),\n  (1102, 11, 'CYT-2', 'Explica el mundo físico basándose en conocimientos sobre los seres vivos, materia y energía, biodiversidad, Tierra y universo.', 2),\n  (1103, 11, 'CYT-3', 'Diseña y construye soluciones tecnológicas para resolver problemas de su entorno.', 3),\n  -- 12. Competencias Transversales (no asociadas a un área)\n  (1201, 12, 'TRANS-1', 'Se desenvuelve en entornos virtuales generados por las TIC.', 1),\n  (1202, 12, 'TRANS-2', 'Gestiona su aprendizaje de manera autónoma.', 2)\nON CONFLICT (id) DO UPDATE SET\n  area_id = EXCLUDED.area_id, code = EXCLUDED.code, name = EXCLUDED.name,\n  display_order = EXCLUDED.display_order, active = true;\n\nDO $$ BEGIN\n  IF (SELECT count(*) FROM competencies WHERE active) <> 31 THEN\n    RAISE EXCEPTION 'competencies debe tener 31 filas activas (actual: %)',\n      (SELECT count(*) FROM competencies WHERE active);\n  END IF;\nEND $$;\n\n-- ─── 4. courses.area_id / users.area_id ───────────────────────────────────────\n-- courses.name se conserva como nombre visible (lo usa el join\n-- `c.name = se.subject` de la migración 007 y la leyenda de horario del\n-- padre); area_id es la clave semántica nueva.\nALTER TABLE courses ADD COLUMN IF NOT EXISTS area_id SMALLINT REFERENCES curricular_areas(id);\nCREATE UNIQUE INDEX IF NOT EXISTS uq_courses_area_section\n  ON courses(grade, section, area_id, year) WHERE area_id IS NOT NULL;\n\nALTER TABLE users ADD COLUMN IF NOT EXISTS area_id SMALLINT REFERENCES curricular_areas(id);\nCOMMENT ON COLUMN users.area_id IS 'Área curricular que dicta el docente (reemplaza gradualmente a users.subject, que sigue existiendo para no romper lecturas viejas)';\n\n-- Backfill best-effort por nombre viejo → area_id, solo aplica a un volumen\n-- ya sembrado con el catálogo anterior (en initdb sobre volumen nuevo esto\n-- es un no-op porque courses/users todavía no tienen filas). Cívica y HGE\n-- no tienen equivalente 1:1 nuevo (se repartieron entre DPCC/CCSS) y\n-- Tutoría desaparece, así que esas tres quedan sin backfill (area_id NULL).\nUPDATE courses SET area_id = m.area_id\nFROM (VALUES\n  ('Matemáticas', 10), ('Comunicación', 6), ('Ciencia y Tecnología', 11),\n  ('Religión', 3), ('Arte', 7), ('Educación Física', 5), ('EPT', 4),\n  ('Inglés', 9)\n) AS m(name, area_id)\nWHERE courses.name = m.name AND courses.area_id IS NULL;\n\nUPDATE users SET area_id = m.area_id\nFROM (VALUES\n  ('Matemáticas', 10), ('Comunicación', 6), ('Ciencia y Tecnología', 11),\n  ('Religión', 3), ('Arte', 7), ('Educación Física', 5), ('EPT', 4),\n  ('Inglés', 9)\n) AS m(subject, area_id)\nWHERE users.subject = m.subject AND users.area_id IS NULL;\n\n-- ─── 5. Tutores de sección ────────────────────────────────────────────────────\n-- Quién califica las competencias transversales (no tienen curso propio) y\n-- de dónde sale enrollments.tutor ahora que el curso \"Tutoría\" desaparece.\nCREATE TABLE IF NOT EXISTS section_tutors (\n  id         UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  grade      TEXT NOT NULL,\n  section    TEXT NOT NULL,\n  year       SMALLINT NOT NULL DEFAULT 2026,\n  teacher_id UUID REFERENCES users(id) ON DELETE SET NULL,\n  UNIQUE (grade, section, year)\n);\n\n-- ─── 6. Notas por competencia ─────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS competency_grades (\n  id            UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  student_id    UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,\n  competency_id SMALLINT NOT NULL REFERENCES competencies(id) ON DELETE RESTRICT,\n  course_id     UUID REFERENCES courses(id) ON DELETE SET NULL,  -- NULL en transversales\n  bimester      SMALLINT NOT NULL CHECK (bimester BETWEEN 1 AND 4),\n  year          SMALLINT NOT NULL DEFAULT 2026,\n  score         NUMERIC(4,2) CHECK (score BETWEEN 0 AND 20),\n  -- Columna generada (no trigger, a diferencia de grades.letter_grade en la\n  -- migración 005): aquí `score` es una columna normal, no otra generada,\n  -- así que Postgres sí permite generada→función. Si la escala cambiara,\n  -- hay que DROP+ADD COLUMN en una migración nueva (los valores existentes\n  -- no se recalculan solos con un CREATE OR REPLACE de nivel_logro).\n  level         grade_level GENERATED ALWAYS AS (nivel_logro(score)) STORED,\n  conclusion    TEXT,\n  registered_by UUID REFERENCES users(id) ON DELETE SET NULL,\n  registered_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (student_id, competency_id, bimester, year)\n);\nCOMMENT ON COLUMN competency_grades.level IS 'AD 18-20, A 16-17, B 11-15, C 0-10. Generada desde score vía nivel_logro().';\nCOMMENT ON COLUMN competency_grades.course_id IS 'Procedencia (qué curso/docente la registró); NULL en competencias transversales. No forma parte de la UNIQUE: si el curso se reasigna, la nota no se duplica.';\n\nCREATE INDEX IF NOT EXISTS idx_cg_student_year   ON competency_grades(student_id, year);\nCREATE INDEX IF NOT EXISTS idx_cg_course_bim     ON competency_grades(course_id, bimester);\nCREATE INDEX IF NOT EXISTS idx_cg_competency_bim ON competency_grades(competency_id, bimester);\n\nDROP TRIGGER IF EXISTS trg_competency_grades_updated_at ON competency_grades;\nCREATE TRIGGER trg_competency_grades_updated_at\n  BEFORE UPDATE ON competency_grades\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n\n-- ─── 7. RLS (paridad con grades; la app conecta como supabase_admin y no la\n--        aplica en runtime, pero dejar la tabla sin RLS mientras sus\n--        hermanas la tienen es una inconsistencia que alguien \"arreglará\" mal\n--        después) ────────────────────────────────────────────────────────────\n-- Mismo guard que 00000000000004_rls_policies.sql: localmente no existen\n-- los roles `authenticated`/`anon` ni auth.uid() (no hay Supabase Auth), así\n-- que sin este guard `CREATE POLICY ... TO authenticated` revienta con\n-- \"role authenticated does not exist\" y aborta TODO el initdb (fatal para\n-- las migraciones siguientes). En Supabase Cloud sí aplica.\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname = 'auth' AND p.proname = 'uid'\n  ) THEN\n    RAISE NOTICE 'auth.uid() no disponible: saltando políticas RLS de competency_grades.';\n    RETURN;\n  END IF;\n\n  ALTER TABLE competency_grades ENABLE ROW LEVEL SECURITY;\n\n  DROP POLICY IF EXISTS \"competency_grades_select_role\" ON competency_grades;\n  CREATE POLICY \"competency_grades_select_role\" ON competency_grades\n    FOR SELECT TO authenticated\n    USING (\n      EXISTS (SELECT 1 FROM students s WHERE s.id = competency_grades.student_id AND s.parent_id = auth.uid())\n      OR EXISTS (SELECT 1 FROM courses c WHERE c.id = competency_grades.course_id AND c.teacher_id = auth.uid())\n      OR EXISTS (\n        SELECT 1 FROM students s\n        JOIN section_tutors t ON t.grade = s.grade AND t.section = s.section AND t.year = competency_grades.year\n        WHERE s.id = competency_grades.student_id AND t.teacher_id = auth.uid()\n      )\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\n    );\n\n  DROP POLICY IF EXISTS \"competency_grades_write_teacher_or_admin\" ON competency_grades;\n  CREATE POLICY \"competency_grades_write_teacher_or_admin\" ON competency_grades\n    FOR ALL TO authenticated\n    USING (\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = competency_grades.course_id AND c.teacher_id = auth.uid())\n      OR EXISTS (\n        SELECT 1 FROM students s\n        JOIN section_tutors t ON t.grade = s.grade AND t.section = s.section AND t.year = competency_grades.year\n        WHERE s.id = competency_grades.student_id AND t.teacher_id = auth.uid()\n      )\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\n    )\n    WITH CHECK (\n      EXISTS (SELECT 1 FROM courses c WHERE c.id = competency_grades.course_id AND c.teacher_id = auth.uid())\n      OR EXISTS (\n        SELECT 1 FROM students s\n        JOIN section_tutors t ON t.grade = s.grade AND t.section = s.section AND t.year = competency_grades.year\n        WHERE s.id = competency_grades.student_id AND t.teacher_id = auth.uid()\n      )\n      OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin')\n    );\nEND $$;\n\n-- ─── 8. Vistas de rollup ───────────────────────────────────────────────────────\n-- v_area_grades: promedio de las competencias de un área por (alumno, curso,\n-- bimestre) — uso INTERNO para dashboards (promedio de aula, distribución,\n-- \"en riesgo\"). SIAGIE no promedia competencias para dar una nota de área;\n-- esta vista NO debe imprimirse en la libreta, que muestra letra por\n-- competencia.\nCREATE OR REPLACE VIEW v_area_grades AS\nSELECT cg.student_id,\n       cg.course_id,\n       c.area_id,\n       cg.bimester,\n       cg.year,\n       ROUND(AVG(cg.score)::numeric, 2)                  AS score,\n       nivel_logro(ROUND(AVG(cg.score)::numeric, 2))     AS level,\n       COUNT(cg.score)::int                              AS graded,\n       (SELECT COUNT(*) FROM competencies c2\n         WHERE c2.area_id = c.area_id AND c2.active)::int AS expected\nFROM competency_grades cg\nJOIN competencies c ON c.id = cg.competency_id\nWHERE cg.score IS NOT NULL\nGROUP BY cg.student_id, cg.course_id, c.area_id, cg.bimester, cg.year;\nCOMMENT ON VIEW v_area_grades IS 'Agregado interno para dashboards (promedio de aula, distribución, alumnos en riesgo). SIAGIE no promedia competencias: la libreta imprime la letra por competencia, no esto.';\n\n-- v_course_bimester_stats: reemplaza el bloque de subconsultas repetido en\n-- app/api/teacher/courses/route.ts y app/api/admin/courses/route.ts.\n-- graded = expected conserva la semántica de \"bimestre cerrado\" que antes\n-- daba `n3 IS NOT NULL`.\nCREATE OR REPLACE VIEW v_course_bimester_stats AS\nSELECT course_id, bimester, year,\n       COUNT(*)::int                                                        AS entries,\n       COUNT(*) FILTER (WHERE graded = expected)::int                       AS complete,\n       ROUND(AVG(score) FILTER (WHERE graded = expected)::numeric, 2)::float AS avg,\n       COUNT(*) FILTER (WHERE graded = expected AND score >= 11)::int       AS approved,\n       COUNT(*) FILTER (WHERE graded = expected AND score <  11)::int       AS failed\nFROM v_area_grades\nWHERE course_id IS NOT NULL\nGROUP BY course_id, bimester, year;\n" },
  { name: "00000000000009_retirar_grades.sql", sql: "-- =============================================================================\n-- IJFK - Migración 009: retirar `grades` (modelo plano n1/n2/n3)\n-- =============================================================================\n-- La app ya no lee ni escribe `grades` en ningún camino: todo el registro\n-- académico (captura docente/admin, panel del padre, PDF de la libreta,\n-- dashboards) pasa por `competency_grades` + las vistas de rollup\n-- `v_area_grades`/`v_course_bimester_stats` (migración 008). Esta migración\n-- cierra la retirada:\n--\n--   1. Elimina el trigger/función que calculaba la letra vieja\n--      (A 18-20/B 15-17/C 10-14/D 0-9, migración 005) — ya no tiene\n--      consumidores y su escala contradice a `nivel_logro()` (008).\n--   2. Renombra `grades` → `grades_legacy` en vez de borrarla: escotilla de\n--      salida por si hace falta auditar o migrar datos históricos que el\n--      seed no reconstruye (la tabla NO se dropea aquí).\n--\n-- Idempotente: los DROP/rename usan guards (IF EXISTS) para poder reaplicar\n-- sin error sobre un volumen donde ya corrió.\n-- =============================================================================\n\nDROP TRIGGER IF EXISTS trg_grades_letter ON grades;\nDROP FUNCTION IF EXISTS compute_letter_grade();\n\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'grades' AND relkind = 'r')\n     AND NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = 'grades_legacy' AND relkind = 'r') THEN\n    ALTER TABLE grades RENAME TO grades_legacy;\n    RAISE NOTICE 'grades renombrada a grades_legacy (retirada, no dropeada).';\n  END IF;\nEND $$;\n\nCOMMENT ON TABLE grades_legacy IS 'Retirada en la migración 009 — modelo plano n1/n2/n3 reemplazado por competency_grades (008). Conservada solo como escotilla de salida / auditoría histórica; ningún camino de la app la lee.';\n" },
  { name: "00000000000010_ia.sql", sql: "-- =============================================================================\n-- IJFK - Migración 010: módulo de IA (conclusiones, importador, asistente,\n-- asignación inteligente de cursos)\n-- =============================================================================\n-- 100% aditiva: no toca ninguna tabla existente. Siete tablas nuevas:\n--\n--   ai_usage_log          auditoría + freno de gasto de cada llamada al\n--                         proveedor de IA (tokens, latencia, feature, éxito).\n--   uploaded_files        un registro por archivo guardado en disco\n--                         (UPLOADS_DIR), separado del proceso que lo usa.\n--   import_jobs           cabecera de una importación de notas (Excel/CSV/\n--                         foto): el scope de permisos queda CONGELADO aquí\n--                         para poder re-verificarlo en cada paso posterior.\n--   import_rows           una fila del archivo = un alumno candidato; aquí\n--                         vive el resultado del matching (DNI/orden/nombre/\n--                         fuzzy/IA).\n--   import_cells           una celda = (fila, competencia); aquí viven los\n--                         valores editables por la UI de revisión.\n--   ai_conversations /\n--   ai_messages            historial persistente del asistente conversacional\n--                         (continuidad + auditoría de qué se le dijo a un\n--                         padre sobre un menor).\n--   course_assignment_runs propuestas de asignación docente↔curso generadas\n--                         por el motor determinista, y qué subconjunto aplicó\n--                         el admin.\n--\n-- Deliberadamente NO hay una tabla de \"sugerencias de conclusión\": el\n-- borrador vive en el estado del cliente hasta que el docente pulsa\n-- Guardar, y la escritura real sigue pasando por\n-- competency_grades/saveGradeEntries de siempre. La trazabilidad la da\n-- ai_usage_log (feature='conclusions').\n--\n-- Invariante importante (NO instalar un shim para esto): las migraciones\n-- 000-009 hacen referencia a la tabla `grades`, que la 009 renombró a\n-- `grades_legacy`. Sobre un volumen fresco no hay problema (corren en\n-- orden). Pero 000/004 NO son reejecutables sobre una base que ya pasó por\n-- la 009 — es el propio ledger de scripts/migrate-apply.mjs\n-- (schema_migrations, con auto-baseline) el que garantiza que eso nunca\n-- ocurra. No añadir guardas de compatibilidad aquí para un escenario que el\n-- ledger ya hace imposible.\n--\n-- Idempotente: CREATE TABLE/INDEX IF NOT EXISTS, triggers con DROP+CREATE,\n-- políticas RLS envueltas en el mismo guard auth.uid() que\n-- 00000000000008_competencias.sql (sin él, `CREATE POLICY ... TO\n-- authenticated` aborta TODO el initdb en un volumen local sin Supabase\n-- Auth).\n-- =============================================================================\n\n-- ─── 1. Auditoría y gasto de IA ───────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS ai_usage_log (\n  id                UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  feature           TEXT NOT NULL CHECK (feature IN (\n                       'conclusions', 'import_vision', 'import_match',\n                       'assistant', 'assignment'\n                     )),\n  user_id           UUID REFERENCES users(id) ON DELETE SET NULL,\n  model             TEXT NOT NULL,\n  prompt_tokens     INT,\n  completion_tokens INT,\n  total_tokens      INT,\n  latency_ms        INT,\n  ok                BOOLEAN NOT NULL,\n  error_kind        TEXT,\n  ref_type          TEXT,\n  ref_id            UUID,\n  meta              JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCOMMENT ON TABLE ai_usage_log IS 'Una fila por llamada al proveedor de IA. Alimenta el freno de gasto (AI_DAILY_TOKEN_BUDGET) y el panel /admin/ai.';\n\nCREATE INDEX IF NOT EXISTS idx_ai_usage_created     ON ai_usage_log(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_ai_usage_feature      ON ai_usage_log(feature, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_ai_usage_user         ON ai_usage_log(user_id, created_at DESC);\n\n-- ─── 2. Archivos subidos (Excel/CSV/foto) ─────────────────────────────────────\nCREATE TABLE IF NOT EXISTS uploaded_files (\n  id            UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  owner_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  feature       TEXT NOT NULL,\n  original_name TEXT NOT NULL,\n  stored_path   TEXT NOT NULL,\n  mime          TEXT NOT NULL,\n  size_bytes    INT NOT NULL,\n  sha256        TEXT NOT NULL,\n  status        TEXT NOT NULL DEFAULT 'almacenado' CHECK (status IN ('almacenado', 'eliminado')),\n  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),\n  deleted_at    TIMESTAMPTZ\n);\nCOMMENT ON TABLE uploaded_files IS 'Registro de archivos en UPLOADS_DIR (volumen Docker). El nombre original del cliente nunca forma parte de stored_path (evita path traversal); solo se guarda como metadato aquí.';\nCOMMENT ON COLUMN uploaded_files.sha256 IS 'Integridad + deduplicación best-effort.';\n\nCREATE INDEX IF NOT EXISTS idx_uploaded_files_owner ON uploaded_files(owner_id, created_at DESC);\n\n-- ─── 3. Importación de notas: cabecera del job ────────────────────────────────\nCREATE TABLE IF NOT EXISTS import_jobs (\n  id           UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  created_by   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  file_id      UUID REFERENCES uploaded_files(id) ON DELETE SET NULL,\n  kind         TEXT NOT NULL CHECK (kind IN ('excel', 'csv', 'foto')),\n  -- Scope congelado al momento de subir: se vuelve a resolver/verificar con\n  -- resolveGradeScope() en /parse, GET y /commit, no solo aquí.\n  course_id    UUID REFERENCES courses(id) ON DELETE SET NULL,\n  grade        TEXT NOT NULL,\n  section      TEXT NOT NULL,\n  transversal  BOOLEAN NOT NULL DEFAULT false,\n  bimester     SMALLINT NOT NULL CHECK (bimester BETWEEN 1 AND 4),\n  year         SMALLINT NOT NULL DEFAULT 2026,\n  status       TEXT NOT NULL DEFAULT 'subido' CHECK (status IN (\n                 'subido', 'analizando', 'revision', 'aplicado', 'descartado', 'error'\n               )),\n  source_meta  JSONB NOT NULL DEFAULT '{}'::jsonb,\n  summary      JSONB NOT NULL DEFAULT '{}'::jsonb,\n  error        TEXT,\n  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCOMMENT ON TABLE import_jobs IS 'Un job por archivo subido. course_id/grade/section/transversal/bimester son el scope congelado que resolveGradeScope() vuelve a verificar en cada paso.';\n\nCREATE INDEX IF NOT EXISTS idx_import_jobs_created_by ON import_jobs(created_by, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_import_jobs_status     ON import_jobs(status);\n\nDROP TRIGGER IF EXISTS trg_import_jobs_updated_at ON import_jobs;\nCREATE TRIGGER trg_import_jobs_updated_at\n  BEFORE UPDATE ON import_jobs\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n\n-- ─── 4. Importación de notas: filas (alumnos candidatos) ──────────────────────\nCREATE TABLE IF NOT EXISTS import_rows (\n  id                  UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  job_id              UUID NOT NULL REFERENCES import_jobs(id) ON DELETE CASCADE,\n  row_index           INT NOT NULL,\n  raw                 JSONB NOT NULL,\n  raw_order           INT,\n  raw_dni             TEXT,\n  raw_name            TEXT,\n  matched_student_id  UUID REFERENCES students(id) ON DELETE SET NULL,\n  match_method        TEXT CHECK (match_method IN (\n                         'dni', 'orden', 'nombre_exacto', 'nombre_normalizado',\n                         'fuzzy', 'ia', 'manual'\n                       )),\n  match_score         NUMERIC(4,3),\n  status              TEXT NOT NULL DEFAULT 'ok' CHECK (status IN ('ok', 'ambiguo', 'sin_match', 'omitido')),\n  issues              JSONB NOT NULL DEFAULT '[]'::jsonb,\n  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (job_id, row_index)\n);\nCOMMENT ON TABLE import_rows IS 'Una fila del archivo original = un alumno candidato. match_method=\"ia\" siempre queda con status=\"ambiguo\": la IA sugiere, un humano confirma con un clic.';\n\nCREATE INDEX IF NOT EXISTS idx_import_rows_job ON import_rows(job_id);\n\nDROP TRIGGER IF EXISTS trg_import_rows_updated_at ON import_rows;\nCREATE TRIGGER trg_import_rows_updated_at\n  BEFORE UPDATE ON import_rows\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n\n-- ─── 5. Importación de notas: celdas (fila × competencia) ─────────────────────\nCREATE TABLE IF NOT EXISTS import_cells (\n  id             UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  job_id         UUID NOT NULL REFERENCES import_jobs(id) ON DELETE CASCADE,\n  row_id         UUID NOT NULL REFERENCES import_rows(id) ON DELETE CASCADE,\n  competency_id  SMALLINT REFERENCES competencies(id) ON DELETE RESTRICT,\n  column_label   TEXT,\n  raw_value      TEXT,\n  score          NUMERIC(4,2) CHECK (score BETWEEN 0 AND 20),\n  conclusion     TEXT,\n  status         TEXT NOT NULL DEFAULT 'ok' CHECK (status IN ('ok', 'invalido', 'vacio', 'sin_mapear')),\n  issue          TEXT,\n  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (row_id, competency_id)\n);\nCOMMENT ON TABLE import_cells IS 'Un JSONB por fila obligaría a leer-modificar-escribir toda la fila en cada PATCH de la UI de revisión; celdas separadas evitan esa carrera. IMPORTANTE: score NULL nunca debe llegar a saveGradeEntries() como entrada de commit (ese caso significa DELETE ahí) — el commit filtra status=''ok'' AND score IS NOT NULL antes de construir SaveEntryInput[].';\n\nCREATE INDEX IF NOT EXISTS idx_import_cells_job ON import_cells(job_id);\nCREATE INDEX IF NOT EXISTS idx_import_cells_row ON import_cells(row_id);\n\nDROP TRIGGER IF EXISTS trg_import_cells_updated_at ON import_cells;\nCREATE TRIGGER trg_import_cells_updated_at\n  BEFORE UPDATE ON import_cells\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n\n-- ─── 6. Asistente conversacional ───────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS ai_conversations (\n  id               UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id          UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  title            TEXT,\n  role_at_creation user_role NOT NULL,\n  message_count    INT NOT NULL DEFAULT 0,\n  last_message_at  TIMESTAMPTZ,\n  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_conversations_user ON ai_conversations(user_id, last_message_at DESC);\n\nDROP TRIGGER IF EXISTS trg_ai_conversations_updated_at ON ai_conversations;\nCREATE TRIGGER trg_ai_conversations_updated_at\n  BEFORE UPDATE ON ai_conversations\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n\nCREATE TABLE IF NOT EXISTS ai_messages (\n  id              UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  conversation_id UUID NOT NULL REFERENCES ai_conversations(id) ON DELETE CASCADE,\n  seq             INT NOT NULL,\n  role            TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'tool', 'system')),\n  content         TEXT,\n  tool_name       TEXT,\n  tool_calls      JSONB,\n  tool_result     JSONB,\n  total_tokens    INT,\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (conversation_id, seq)\n);\nCOMMENT ON TABLE ai_messages IS 'Auditoría de qué le dijo la IA a un padre/docente/admin sobre datos de un menor. Retención: cleanup_old_ai_conversations() borra conversaciones con last_message_at < 90 días, invocada perezosamente al crear una conversación nueva.';\n\nCREATE INDEX IF NOT EXISTS idx_ai_messages_conversation ON ai_messages(conversation_id, seq);\n\n-- Retención de 90 días — mismo patrón que cleanup_expired_pending_registrations()\n-- de 00000000000001_registration.sql. No hay pg_cron en esta imagen; se invoca\n-- de forma perezosa (best-effort, fire-and-forget) al crear una conversación.\nCREATE OR REPLACE FUNCTION cleanup_old_ai_conversations()\nRETURNS void\nLANGUAGE sql AS $$\n  DELETE FROM ai_conversations\n  WHERE last_message_at IS NOT NULL AND last_message_at < now() - interval '90 days';\n$$;\n\n-- ─── 7. Asignación inteligente de cursos ───────────────────────────────────────\nCREATE TABLE IF NOT EXISTS course_assignment_runs (\n  id             UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  created_by     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  scope          JSONB NOT NULL,\n  proposals      JSONB NOT NULL,\n  applied_count  INT NOT NULL DEFAULT 0,\n  applied_at     TIMESTAMPTZ,\n  explanation    TEXT,\n  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCOMMENT ON TABLE course_assignment_runs IS 'Qué propuso el motor determinista frente a qué aplicó el admin — evidencia auditable de que la IA solo explica, no decide (ver lib/courses/assignment.ts).';\n\nCREATE INDEX IF NOT EXISTS idx_assignment_runs_created_by ON course_assignment_runs(created_by, created_at DESC);\n\nDROP TRIGGER IF EXISTS trg_assignment_runs_updated_at ON course_assignment_runs;\nCREATE TRIGGER trg_assignment_runs_updated_at\n  BEFORE UPDATE ON course_assignment_runs\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n\n-- ─── 8. RLS ────────────────────────────────────────────────────────────────────\n-- Mismo guard que 00000000000008_competencias.sql: localmente no existen los\n-- roles authenticated/anon ni auth.uid() (no hay Supabase Auth local), así que\n-- sin este guard CREATE POLICY ... TO authenticated aborta TODO el initdb.\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname = 'auth' AND p.proname = 'uid'\n  ) THEN\n    RAISE NOTICE 'auth.uid() no disponible: saltando políticas RLS del módulo de IA.';\n    RETURN;\n  END IF;\n\n  ALTER TABLE uploaded_files ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"uploaded_files_owner_or_admin\" ON uploaded_files;\n  CREATE POLICY \"uploaded_files_owner_or_admin\" ON uploaded_files\n    FOR ALL TO authenticated\n    USING (owner_id = auth.uid() OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\n\n  ALTER TABLE import_jobs ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"import_jobs_owner_or_admin\" ON import_jobs;\n  CREATE POLICY \"import_jobs_owner_or_admin\" ON import_jobs\n    FOR ALL TO authenticated\n    USING (created_by = auth.uid() OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\n\n  ALTER TABLE import_rows ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"import_rows_via_job\" ON import_rows;\n  CREATE POLICY \"import_rows_via_job\" ON import_rows\n    FOR ALL TO authenticated\n    USING (EXISTS (\n      SELECT 1 FROM import_jobs j\n      WHERE j.id = import_rows.job_id\n        AND (j.created_by = auth.uid() OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\n    ));\n\n  ALTER TABLE import_cells ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"import_cells_via_job\" ON import_cells;\n  CREATE POLICY \"import_cells_via_job\" ON import_cells\n    FOR ALL TO authenticated\n    USING (EXISTS (\n      SELECT 1 FROM import_jobs j\n      WHERE j.id = import_cells.job_id\n        AND (j.created_by = auth.uid() OR EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'))\n    ));\n\n  ALTER TABLE ai_conversations ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"ai_conversations_owner\" ON ai_conversations;\n  CREATE POLICY \"ai_conversations_owner\" ON ai_conversations\n    FOR ALL TO authenticated\n    USING (user_id = auth.uid());\n\n  ALTER TABLE ai_messages ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"ai_messages_via_conversation\" ON ai_messages;\n  CREATE POLICY \"ai_messages_via_conversation\" ON ai_messages\n    FOR ALL TO authenticated\n    USING (EXISTS (\n      SELECT 1 FROM ai_conversations c WHERE c.id = ai_messages.conversation_id AND c.user_id = auth.uid()\n    ));\n\n  ALTER TABLE ai_usage_log ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"ai_usage_log_admin_only\" ON ai_usage_log;\n  CREATE POLICY \"ai_usage_log_admin_only\" ON ai_usage_log\n    FOR SELECT TO authenticated\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\n\n  ALTER TABLE course_assignment_runs ENABLE ROW LEVEL SECURITY;\n  DROP POLICY IF EXISTS \"course_assignment_runs_admin_only\" ON course_assignment_runs;\n  CREATE POLICY \"course_assignment_runs_admin_only\" ON course_assignment_runs\n    FOR ALL TO authenticated\n    USING (EXISTS (SELECT 1 FROM users u WHERE u.id = auth.uid() AND u.role = 'admin'));\nEND $$;\n" },
];
